package ocean.service;
import ocean.database.DatabaseConnection;import ocean.model.FutureLetter;import ocean.utils.ValidationUtil;import java.sql.*;import java.time.*;import java.util.*;
public class FutureLetterService implements Service {
 public void initialize()throws SQLException{DatabaseConnection.initialize();}
 public FutureLetter save(String text,LocalDate date,String ownerId)throws SQLException{String clean=ValidationUtil.validate(text);if(date==null||date.isBefore(LocalDate.now()))throw new IllegalArgumentException("Choose today or a date in the future.");FutureLetter f=new FutureLetter(clean,date);try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement("INSERT INTO future_letters(letter_id,letter_text,target_date,created_at,owner_id) VALUES(?,?,?,?,?)")){p.setString(1,f.getId());p.setString(2,f.getText());p.setString(3,date.toString());p.setString(4,f.getCreatedAt().toString());p.setString(5,ownerId);p.executeUpdate();}return f;}
 public List<FutureLetter> all(String ownerId)throws SQLException{List<FutureLetter> a=new ArrayList<>();try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT * FROM future_letters WHERE owner_id=? ORDER BY target_date")){p.setString(1,ownerId);try(ResultSet r=p.executeQuery()){while(r.next())a.add(new FutureLetter(r.getString("letter_id"),r.getString("letter_text"),LocalDate.parse(r.getString("target_date")),LocalDateTime.parse(r.getString("created_at"))));}}return a;}
 public int count(String ownerId)throws SQLException{try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT COUNT(*) FROM future_letters WHERE owner_id=?")){p.setString(1,ownerId);try(ResultSet r=p.executeQuery()){return r.next()?r.getInt(1):0;}}}
}
